/** TDS1 detection and API transport. No game decryption keys are present in this client. */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    SAVE_DECODE_PUBLIC_KEY, SAVE_DECODE_API_ENDPOINT, SAVE_DECODE_PROJECT_ID, isEncryptedSave, decryptSave
 * depends    src/save-decoder/types
 * used by    src/node/decode-save, src/save-decoder/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import { z } from 'zod'
import type { SaveDecodeApiOptions } from './types'

export const SAVE_DECODE_PUBLIC_KEY = 'thetowersdk-public-v1'
export const SAVE_DECODE_API_ENDPOINT = 'https://appwrite.the-tower-run-tracker.com/v1/functions/save-decode/executions'
export const SAVE_DECODE_PROJECT_ID = '68190de700097b8f59df'
const MAX_SAVE_BYTES = 8 * 1024 * 1024
const MAX_BASE64 = Math.ceil(MAX_SAVE_BYTES / 3) * 4
const executionSchema = z.object({
  status: z.literal('completed'),
  responseStatusCode: z.number().int().min(100).max(599),
  responseBody: z.string().max(MAX_BASE64 + 1024),
})
const payloadSchema = z.object({ decryptedBase64: z.string().min(4).max(MAX_BASE64).regex(/^[A-Za-z0-9+/]+={0,2}$/) }).strict()

export function isEncryptedSave(bytes: Uint8Array): boolean {
  return bytes.length >= 4 && bytes[0] === 0x54 && bytes[1] === 0x44 && bytes[2] === 0x53 && bytes[3] === 0x31
}

function encode(bytes: Uint8Array): string {
  let binary = ''
  for (let offset = 0; offset < bytes.length; offset += 8192) {
    binary += String.fromCharCode(...bytes.subarray(offset, offset + 8192))
  }
  return btoa(binary)
}

async function readResponse(response: Response): Promise<unknown> {
  const reader = response.body?.getReader()
  if (!reader) throw new Error('The save-decode API returned an empty response.')
  const chunks: Uint8Array[] = []
  let length = 0
  try {
    while (true) {
      const { done, value } = await reader.read()
      if (done) break
      length += value.byteLength
      if (length > MAX_BASE64 + 64 * 1024) {
        await reader.cancel()
        throw new Error('The save-decode API response exceeds the size limit.')
      }
      chunks.push(value)
    }
  }
  finally { reader.releaseLock() }
  const bytes = new Uint8Array(length)
  let offset = 0
  for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.length }
  try { return JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes)) }
  catch { throw new Error('The save-decode API returned an invalid response.') }
}

/** Obtain decrypted bytes from Appwrite; decompression and parsing remain local. */
export async function decryptSave(bytes: Uint8Array, options?: SaveDecodeApiOptions): Promise<Uint8Array> {
  if (!isEncryptedSave(bytes)) return bytes
  if (bytes.byteLength > MAX_SAVE_BYTES) throw new Error('Encrypted save exceeds the 8 MiB upload limit.')
  const endpoint = new URL(options?.endpoint ?? SAVE_DECODE_API_ENDPOINT)
  if (endpoint.protocol !== 'https:') throw new Error('The save-decode API requires an HTTPS endpoint.')
  // Own the input before the first await; custom views cannot change the submitted save.
  const body = JSON.stringify({
    body: JSON.stringify({ saveBase64: encode(bytes) }),
    async: false,
    method: 'POST',
    headers: { 'content-type': 'application/json', 'x-save-api-key': options?.apiKey ?? SAVE_DECODE_PUBLIC_KEY },
  })
  const response = await fetch(endpoint, {
    method: 'POST',
    headers: { 'content-type': 'application/json', 'x-appwrite-project': options?.projectId ?? SAVE_DECODE_PROJECT_ID },
    body,
    credentials: 'omit',
    cache: 'no-store',
    redirect: 'error',
    signal: options?.signal,
  })
  if (!response.ok) throw new Error(`Save decryption failed (HTTP ${response.status}).`)
  const execution = executionSchema.safeParse(await readResponse(response))
  if (!execution.success) throw new Error('The save-decode API returned an invalid execution response.')
  if (execution.data.responseStatusCode !== 200) {
    throw new Error(`Save decryption failed (HTTP ${execution.data.responseStatusCode}).`)
  }
  let payload
  try { payload = payloadSchema.parse(JSON.parse(execution.data.responseBody)) }
  catch { throw new Error('The save-decode API returned invalid decrypted bytes.') }
  let binary: string
  try { binary = atob(payload.decryptedBase64) }
  catch { throw new Error('The save-decode API returned invalid base64.') }
  if (binary.length > MAX_SAVE_BYTES || btoa(binary) !== payload.decryptedBase64) {
    throw new Error('The save-decode API returned invalid decrypted bytes.')
  }
  const decrypted = Uint8Array.from(binary, character => character.charCodeAt(0))
  if (isEncryptedSave(decrypted)) throw new Error('The save-decode API returned encrypted bytes.')
  return decrypted
}
